function boxHtml(){const selected=eligibleCards(data.cards,learningVocabularySettings(p(),course,data.sections,Date.now()));return `<div class="boxes" aria-label="Five Leitner boxes">${[1,2,3,4,5].map((b,i)=>`<button class="box" data-action="box-filter" data-id="${b}"><small>BOX ${b}</small><b>${selected.filter(c=>(p().progress[c.id]?.box||1)===b).length}</b><small>${[1,2,4,7,14][i]}-day interval</small></button>`).join('')}</div>`;}
